    [Static assets] Fix ETag mismatch in static assets during development (#64611)

    * Truncates the LastWriteTime on the file to the second for comparison against the manifest (since the manifest is truncated to the second at generation time) to avoid detecting the file as changed when it hasn't.

diff --git a/src/StaticAssets/src/Development/StaticAssetDevelopmentRuntimeHandler.cs b/src/StaticAssets/src/Development/StaticAssetDevelopmentRuntimeHandler.cs
index 14ed7a0c3b..42e680ea12 100644
--- a/src/StaticAssets/src/Development/StaticAssetDevelopmentRuntimeHandler.cs
+++ b/src/StaticAssets/src/Development/StaticAssetDevelopmentRuntimeHandler.cs
@@ -57,7 +57,10 @@ internal sealed partial class StaticAssetDevelopmentRuntimeHandler
         {
             var originalFeature = context.Features.GetRequiredFeature<IHttpResponseBodyFeature>();
             var fileInfo = context.RequestServices.GetRequiredService<IWebHostEnvironment>().WebRootFileProvider.GetFileInfo(asset.AssetPath);
-            if (fileInfo.Length != asset.GetContentLength() || fileInfo.LastModified != asset.GetLastModified())
+            // Truncating is correct because the manifest truncates the timestamp when it serializes the Last-Modified header
+            // (HTTP date format only supports second precision). We need to apply the same truncation here so that we correctly
+            // detect unchanged files rather than always seeing them as different due to subsecond precision mismatch.
+            if (fileInfo.Length != asset.GetContentLength() || TruncateToSeconds(fileInfo.LastModified) != asset.GetLastModified())
             {
                 // At this point, we know that the file has changed from what was generated at build time.
                 // This is for example, when someone changes something in the WWWRoot folder.
@@ -129,6 +132,18 @@ internal sealed partial class StaticAssetDevelopmentRuntimeHandler
         return $"\"{Convert.ToBase64String(SHA256.HashData(stream))}\"";
     }

+    internal static DateTimeOffset TruncateToSeconds(DateTimeOffset dateTimeOffset)
+    {
+        return new DateTimeOffset(
+            dateTimeOffset.Year,
+            dateTimeOffset.Month,
+            dateTimeOffset.Day,
+            dateTimeOffset.Hour,
+            dateTimeOffset.Minute,
+            dateTimeOffset.Second,
+            dateTimeOffset.Offset);
+    }
+
     internal sealed class RuntimeStaticAssetResponseBodyFeature : IHttpResponseBodyFeature
     {
         private readonly IHttpResponseBodyFeature _original;
diff --git a/src/StaticAssets/test/StaticAssetsIntegrationTests.cs b/src/StaticAssets/test/StaticAssetsIntegrationTests.cs
index 2fda7c8707..c44f0c3fde 100644
--- a/src/StaticAssets/test/StaticAssetsIntegrationTests.cs
+++ b/src/StaticAssets/test/StaticAssetsIntegrationTests.cs
@@ -1098,4 +1098,45 @@ public class StaticAssetsIntegrationTests
             }
         }
     }
+
+    [Fact]
+    public void TruncateToSeconds_RemovesSubsecondComponents()
+    {
+        var original = new DateTimeOffset(2023, 5, 15, 10, 30, 45, 123, TimeSpan.FromHours(2));
+
+        var truncated = StaticAssetDevelopmentRuntimeHandler.TruncateToSeconds(original);
+
+        Assert.Equal(2023, truncated.Year);
+        Assert.Equal(5, truncated.Month);
+        Assert.Equal(15, truncated.Day);
+        Assert.Equal(10, truncated.Hour);
+        Assert.Equal(30, truncated.Minute);
+        Assert.Equal(45, truncated.Second);
+        Assert.Equal(0, truncated.Millisecond);
+        Assert.Equal(TimeSpan.FromHours(2), truncated.Offset);
+    }
+
+    [Fact]
+    public void TruncateToSeconds_PreservesUtcOffset()
+    {
+        var utcDateTime = new DateTimeOffset(2023, 5, 15, 10, 30, 45, 500, TimeSpan.Zero);
+
+        var truncated = StaticAssetDevelopmentRuntimeHandler.TruncateToSeconds(utcDateTime);
+
+        Assert.Equal(TimeSpan.Zero, truncated.Offset);
+        Assert.Equal(0, truncated.Millisecond);
+    }
+
+    [Fact]
+    public void TruncateToSeconds_MatchesHttpDateFormat()
+    {
+        var original = new DateTimeOffset(2023, 5, 15, 10, 30, 45, 789, TimeSpan.Zero);
+
+        var httpFormatted = original.ToString("ddd, dd MMM yyyy HH:mm:ss 'GMT'", CultureInfo.InvariantCulture);
+        var parsed = DateTimeOffset.Parse(httpFormatted, CultureInfo.InvariantCulture);
+
+        var truncated = StaticAssetDevelopmentRuntimeHandler.TruncateToSeconds(original);
+
+        Assert.Equal(parsed, truncated);
+    }
 }
